/* Cause / contribution / learning are independent, and role-skill links require student review. */
Object.assign(ds,{taxonomyV2:true,roleArea:'any',format:'any',useSkills:[],learnSkills:[],roles:[],roleDraft:[]});
const skillNames=[...new Set(Object.values(DM.groups).flatMap(g=>g.skills))];
function skillOptions(){return Object.entries(DM.groups).map(([k,g])=>`<optgroup label="${esc(g.name)}">${g.skills.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</optgroup>`).join('')}
function skillPicker(field,label){return `<div class="skill-picker"><label class="field" for="${field}-select">${label}</label><div class="skill-add-row"><select id="${field}-select">${skillOptions()}</select><button class="btn secondary" aria-label="Add ${label.toLowerCase()}" onclick="addInterestSkill('${field}')">+</button></div><div class="skill-tags">${ds[field].map(s=>`<button class="skill-tag" onclick="removeInterestSkill('${field}','${s}')" aria-label="Remove ${esc(s)} from ${label.toLowerCase()}">${esc(s)} ×</button>`).join('')||'<span class="discover-note">Open to suggestions</span>'}</div></div>`}
function addInterestSkill(field){const s=document.getElementById(field+'-select').value;if(!ds[field].includes(s))ds[field].push(s);render()}
function removeInterestSkill(field,skill){ds[field]=ds[field].filter(s=>s!==skill);render()}
function dSkillSearch(skill){ds.useSkills=[skill];ds.mode='experience';ds.tab='recommended';ds.roleArea='any';ds.cause='any';go('/discover');render();notify('Finding roles where you can use '+skill+'. Choose a cause if you like.')}
function dPreset(which){ds.day='any';ds.format='any';ds.weeks=12;ds.tab='recommended';if(which==='budget'){Object.assign(ds,{mode:'experience',cause:'Food Access & Nutrition',useSkills:['budgeting'],learnSkills:['cost analysis'],roleArea:'any'})}else if(which==='design'){Object.assign(ds,{mode:'learn',cause:'Animal Welfare',useSkills:[],learnSkills:['design','writing'],roleArea:'any'})}else{Object.assign(ds,{mode:'interests',cause:'Environment & Conservation',useSkills:[],learnSkills:['planting'],roleArea:'any'})}render()}
dReset=function(){Object.assign(ds,{mode:'experience',roleArea:'any',format:'any',useSkills:[],learnSkills:[],cause:'any',day:'any',transport:'transit',maxTravel:45,weeks:12,maxCost:15});render()};
dStatus=function(r){return ({excluded:'Outside your limits',conditional:'Details to confirm',training:'Training first',review:'Review role requirements',ready:r.opportunity.level||'Explore this role'})[r.status]};
dWhy=function(r){let o=r.opportunity;let bits=[];if(ds.cause!=='any')bits.push(o.cause===ds.cause?'Supports your chosen cause.':'A different cause to explore.');if(ds.mode==='interests')bits.push('Your current interests lead; past experience has no ranking weight.');else if(r.useMatches.length)bits.push('Use '+esc(r.useMatches.join(', '))+' in a concrete contribution.');if(r.learnMatches.length)bits.push('Practice '+esc(r.learnMatches.join(', '))+' with the listed support.');if(ds.mode==='experience'&&r.matched.length){let m=r.matched[0];bits.push('Connects with '+esc(m.skill)+' from '+esc(m.role)+'.')}return bits.join(' ')||esc(o.outcome)};
function dBackgroundSummary(){return `<section class="card tip"><span class="eyebrow">EXPERIENCE → SKILLS → POSSIBILITIES</span><h3 style="margin-top:12px">${ds.reviewed?'Build on a real responsibility.':'What have you done before?'}</h3><p class="discover-note">${ds.reviewed?'Choose a skill below to find related work across causes.':'Add role descriptions from your resume or LinkedIn. Review which skills you actually used in each role.'}</p>${ds.reviewed?ds.roles.map(r=>`<div class="role-mini"><strong>${esc(r.title)}</strong><div class="skill-tags">${r.skills.map(s=>`<button class="skill-tag" onclick="dSkillSearch('${s}')" aria-label="Find roles using ${esc(s)} from ${esc(r.title)}">${esc(s)} ↗</button>`).join('')||'<small>No skills selected for this role.</small>'}</div></div>`).join(''):''}<a class="textlink" href="#/discover/profile">${ds.reviewed?'Edit role experience':'Add my role experience'} →</a><p class="discover-note" style="margin:15px 0 0">Self-reported experience. Neither a LinkedIn entry nor a tag proves proficiency.</p></section>`}
dFilter=function(){return `<section class="card"><span class="eyebrow">CAUSE, CONTRIBUTION, CURIOSITY</span><h3 style="margin:10px 0 20px">Make it meaningful.</h3><label class="field">Causes I care about<select onchange="dSelect('cause',this.value)">${dOptions([['any','Open to any cause'],...DM.causes.map(c=>[c,c])],ds.cause)}</select><small>A preference, not a restriction. Other causes stay browsable.</small></label>${skillPicker('useSkills','Skills I want to use')}${skillPicker('learnSkills','Skills I want to develop')}<details><summary class="textlink" style="min-height:40px;cursor:pointer">Format, timing & travel</summary><label class="field" style="margin-top:15px">Contribution area<select onchange="dSelect('roleArea',this.value)">${dOptions([['any','Open to any role'],...Object.entries(DM.groups).map(([k,v])=>[k,v.name])],ds.roleArea)}</select></label><label class="field">Where I contribute<select onchange="dSelect('format',this.value)">${dOptions([['any','Any format'],['inperson','In person'],['remote','Remote'],['hybrid','Hybrid']],ds.format)}</select></label><label class="field">Available day<select onchange="dSelect('day',this.value)">${dOptions(['any','Saturday','Sunday','Wednesday'].map(x=>[x,x==='any'?'Any sample day':x]),ds.day)}</select></label><label class="field">How I travel<select onchange="dSelect('transport',this.value)">${dOptions([['transit','Public transport'],['car','Car'],['bike','Bike']],ds.transport)}</select></label><label class="field">Maximum one-way journey<select onchange="dSelect('maxTravel',this.value)">${dOptions([15,30,45,60,90].map(x=>[x,x+' minutes']),ds.maxTravel)}</select></label><label class="field">Maximum commitment<select onchange="dSelect('weeks',this.value)">${dOptions([[1,'One event'],[2,'Up to 2 weeks'],[6,'Up to 6 weeks'],[12,'Up to 12 weeks']],ds.weeks)}</select></label><label class="field">Maximum travel cost per visit<select onchange="dSelect('maxCost',this.value)">${dOptions([0,5,10,15,25].map(x=>[x,'$'+x]),ds.maxCost)}</select></label><p class="discover-note">Travel limits apply to in-person and hybrid roles. Fully remote roles have no commute. All journeys here are fictional estimates.</p></details><button class="btn secondary wide" onclick="dReset()">Reset preferences</button></section>${dBackgroundSummary()}`};
function formatName(o){return ({inperson:'In person',hybrid:'Hybrid',remote:'Remote'})[o.format]}
function tagsText(values,empty){return values.length?values.map(s=>`<span class="skill-label">${esc(s)}</span>`).join(''):`<span class="discover-note">${empty}</span>`}
dCard=function(r){let o=r.opportunity;return `<article class="card opportunity-card"><div class="opportunity-art">${dArt(o)}<span class="pill">${esc(o.cause)}</span></div><div class="opportunity-content"><div class="card-category"><span class="eyebrow">${esc(DM.groups[o.area].name)}</span><span class="source-label">DEMO</span></div><h3 style="margin-top:10px">${esc(o.role)}</h3><p class="org-name">${esc(o.org)}</p><span class="pill ${r.status==='ready'?'':'pending'}" style="align-self:start">${dStatus(r)}</span><div class="opportunity-meta"><span>${formatName(o)}</span><span>${o.weeks===1?'One event':o.weeks+' weeks'}</span><span>${o.day}</span>${o.format==='remote'?'':`<span>${r.travel===null?'Journey unconfirmed':r.travel+' min · sample '+ds.transport}</span>`}</div><div class="skill-line"><strong>You’ll use</strong><div>${tagsText(o.required,'No prior skills required')}</div></div><div class="skill-line"><strong>You could practice</strong><div>${tagsText(o.practice,'Confirm with the organizer')}</div></div><p class="opportunity-why" style="margin-top:14px">${dWhy(r)}</p><div class="fit-line"><strong>${dScore(r)} fit points</strong><small class="muted">${r.knownWeight<100?'Some details unknown':'Out of 100'}</small></div><div class="fit-meter" aria-hidden="true"><span style="width:${r.low}%"></span></div><p class="source-label" style="margin:10px 0 0">Fictional listing · no verified opening</p><div class="opportunity-actions"><a class="btn" href="#/discover/${o.id}">See role & fit ↗</a><button class="btn secondary save-opportunity" aria-label="${ds.saved.has(o.id)?'Unsave':'Save'} ${esc(o.role)}" aria-pressed="${ds.saved.has(o.id)}" onclick="dBookmark('${o.id}')">${ds.saved.has(o.id)?'✓':'+'}</button></div></div></article>`};
discoverPage=function(){let all=DO.map(o=>DM.evaluate(o,ds));let ranked=DM.rank(DO,ds).filter(r=>!ds.hidden.has(r.opportunity.id));let items=ds.tab==='all'?all:ds.tab==='saved'?all.filter(r=>ds.saved.has(r.opportunity.id)):ranked;return `<section class="discover-hero"><div><span class="eyebrow">GOOD WORK, YOUR WAY</span><h1>Your skills.<br>A cause that matters.</h1><p>Use budgeting to support a food pantry.<br>Try design for animal welfare. Or follow a new curiosity.</p></div><div class="discover-orbit">${icon('leaf')}</div></section><div class="discover-mode-grid">${Object.entries(DM.modes).map(([k,v])=>`<button class="discover-mode" aria-pressed="${ds.mode===k}" onclick="dMode('${k}')"><strong>${v}</strong><span>${k==='experience'?'Find a use for what you already know.':k==='learn'?'Build skills through supported practice.':'Choose a cause, regardless of your resume.'}</span></button>`).join('')}</div><div class="background-entry"><a class="textlink" href="#/discover/profile">${ds.reviewed?'Review my role history':'Add resume or LinkedIn experience'} →</a></div><div class="discovery-presets"><span class="discover-note">Try a direction:</span><button class="skill-tag" onclick="dPreset('budget')">Budgeting + food access ↗</button><button class="skill-tag" onclick="dPreset('design')">Design + animal welfare ↗</button><button class="skill-tag" onclick="dPreset('outdoors')">Explore outdoors ↗</button></div><div class="notice" style="font-size:12px">Interactive prototype · ${DO.length} fictional opportunities. Role-skill matching works locally after your review. Claude, LinkedIn importing, and live listings are not connected.</div><div class="discover-body"><aside class="discover-rail ${ds.showFilters?'expanded':''}" style="position:static;height:auto;border:0;background:transparent;padding:0">${dFilter()}</aside><section><div class="discover-heading"><div><span class="eyebrow">${ds.cause==='any'?'OPEN TO POSSIBILITY':esc(ds.cause)}</span><h2 style="margin-top:6px">${ds.tab==='saved'?'Your saved possibilities':'Find a contribution that fits.'}</h2></div><button class="btn secondary discover-mobile-filters" onclick="ds.showFilters=!ds.showFilters;render()">${ds.showFilters?'Hide preferences':'Preferences'} ☷</button></div><nav class="discover-tabs" aria-label="Opportunity lists">${[['recommended','For you'],['all','Browse all'],['saved','Saved ('+ds.saved.size+')']].map(([k,t])=>`<button aria-pressed="${ds.tab===k}" onclick="ds.tab='${k}';render()">${t}</button>`).join('')}</nav><p class="discover-count" role="status" aria-live="polite">${items.length} ${items.length===1?'possibility':'possibilities'} · ${DM.modes[ds.mode]}</p>${ds.useSkills.length||ds.learnSkills.length?`<div class="selected-direction"><span>Use: ${esc(ds.useSkills.join(', ')||'open')}</span><span>Develop: ${esc(ds.learnSkills.join(', ')||'open')}</span></div>`:''}${ds.hidden.size?'<button class="textlink" style="border:0;background:none;padding:10px 0" onclick="ds.hidden.clear();render()">Restore hidden recommendations</button>':''}<div class="discover-grid">${items.map(dCard).join('')}</div>${items.length?'':`<div class="card empty"><h2>No sample roles in this view.</h2><p class="muted">Change your limits or explore the complete demo catalog.</p><button class="btn secondary" onclick="ds.tab='all';render()">Browse all roles →</button></div>`}<details style="margin-top:25px"><summary class="textlink" style="min-height:44px;cursor:pointer">How these recommendations work</summary><div class="card"><p class="discover-note">We match actual required and practice skills with your chosen contribution and learning goals. Student-reviewed role descriptions provide context; they are not verified skill assessments. Other causes remain browsable. Missing information is unknown, not a failing score.</p><p class="discover-note">${DM.criteria.map((c,i)=>`${c}: ${DM.weights[ds.mode][i]}%`).join(' · ')}</p><p class="discover-note">Scores are unvalidated fit points, not success probabilities. No prestige, major restriction, or badge-count bonus is used. Fully remote roles bypass commute checks.</p></div></details></section></div>`};
function roleReviewHTML(r){return `<section class="role-review"><label class="field">Role title<input type="text" maxlength="100" value="${esc(r.title)}" oninput="updateRoleTitle('${r.id}',this.value)"></label><div class="skill-tags">${r.skills.map(s=>`<button class="skill-tag" onclick="removeRoleSkill('${r.id}','${s}')" aria-label="Remove ${esc(s)} from ${esc(r.title)}">${esc(s)} ×</button>`).join('')||'<span class="discover-note">No skills selected for this role.</span>'}</div><details><summary class="textlink" style="min-height:35px;cursor:pointer">Where these suggestions came from</summary>${r.skills.map(s=>`<div class="evidence-row"><strong>${esc(s)}</strong><p>${esc(r.evidence[s]||'Manually added by you; confirm it reflects this role.')}</p></div>`).join('')}<p class="discover-note">Keyword suggestions can be wrong. Remove a tag if the text describes something you did not do.</p></details><div class="skill-add-row"><select id="role-skill-${r.id}" aria-label="Add a skill to ${esc(r.title)}">${skillOptions()}</select><button class="btn secondary" onclick="addRoleSkill('${r.id}')">Add skill</button></div><button class="textlink" style="border:0;background:none;padding:14px 0" onclick="removeRole('${r.id}')">Remove this role</button></section>`}
dProfile=function(){return `<div class="discover-profile"><a class="textlink" href="#/discover">← Back to Discover</a><div class="intro" style="margin-top:20px"><div><span class="eyebrow">YOUR EXPERIENCE HAS CONTEXT</span><h1>What did you do?<br>What did you use?</h1><p class="muted">Connect skills with the roles where you practiced them.</p></div></div><div class="card"><span class="discover-step">01 · Bring your experience</span><h2 style="margin-top:12px">Start with a role description.</h2><p class="discover-note">Paste resume or LinkedIn experience. Put each role in a separate paragraph, with its title on the first line. Text stays in this page’s memory and clears on refresh. This prototype uses keyword suggestions, not Claude.</p><label class="field" for="background-text">Roles and responsibilities</label><textarea id="background-text" oninput="ds.text=this.value" placeholder="Club Treasurer | Student Association&#10;Prepared event budgets in Excel and compared supply costs.&#10;&#10;Event Coordinator | Community Club&#10;Organized volunteer shifts and outreach.">${esc(ds.text)}</textarea><div class="discover-field-row" style="margin:14px 0"><button class="btn secondary" onclick="dSample()">Try sample role history</button><label class="textlink">Import text resume<input type="file" accept=".txt,.md,text/plain,text/markdown" style="display:block;max-width:100%;font-size:12px;margin-top:8px" onchange="dReadFile(this)"></label></div><label class="field">LinkedIn URL · optional reference<input id="linkedin-reference" type="url" value="${esc(ds.linkedin)}" placeholder="https://www.linkedin.com/in/your-profile" oninput="ds.linkedin=this.value"></label><p class="discover-note">LinkedIn importing is not connected. Paste the relevant experience above. Text/Markdown imports only, up to 200 KB; paste excerpts from PDF or Word.</p><button class="btn wide" onclick="dExtract()">Find skills in these roles →</button></div><div class="card" id="experience-review"><span class="discover-step">02 · Check each connection</span><h2 style="margin-top:12px">Did you use these skills in this role?</h2><p class="discover-note">Edit titles, remove incorrect suggestions, or add skills you used. These are your statements, not verified credentials or proof of mastery.</p>${ds.roleDraft.map(roleReviewHTML).join('')||'<p class="muted">No roles added yet. You can start fresh without a resume.</p>'}<button class="btn secondary" onclick="addBlankRole()">Add a role manually +</button><label class="discover-field-row" style="font-size:13px;margin:22px 0"><input id="review-confirm" type="checkbox" ${ds.draftReviewed?'checked':''} onchange="ds.draftReviewed=this.checked"> I reviewed the role titles and their skill connections.</label><p class="discover-note" id="review-error" role="alert"></p><button class="btn wide" onclick="dConfirmProfile()">Use this role experience</button><button class="btn secondary wide" style="margin-top:10px" onclick="dSkipProfile()">Explore without experience</button></div></div>`};
dSample=function(){ds.text='Club Treasurer | Student Association\nBuilt event budgets in Excel, tracked expenses, and compared supply quotes.\n\nEvent Coordinator | Community Club\nOrganized event logistics, volunteer shifts, and outreach communications.';ds.roleDraft=[];ds.draftReviewed=false;render();notify('Fictional role history loaded. Find and review its skill connections next.')};
dExtract=function(){ds.roleDraft=DM.extractRoles(ds.text);ds.draftReviewed=false;render();document.getElementById('experience-review').scrollIntoView({behavior:'smooth',block:'start'});notify('Review the suggested skill links before using them.')};
function updateRoleTitle(id,title){ds.roleDraft.find(r=>r.id===id).title=title;ds.draftReviewed=false;const c=document.getElementById('review-confirm');if(c)c.checked=false}
function addBlankRole(){ds.roleDraft.push({id:'manual-'+Date.now(),title:'My role',description:'Manually entered role',skills:[],evidence:{}});ds.draftReviewed=false;render()}
function removeRole(id){ds.roleDraft=ds.roleDraft.filter(r=>r.id!==id);ds.draftReviewed=false;render()}
function removeRoleSkill(id,skill){const r=ds.roleDraft.find(r=>r.id===id);r.skills=r.skills.filter(s=>s!==skill);delete r.evidence[skill];ds.draftReviewed=false;render()}
function addRoleSkill(id){const r=ds.roleDraft.find(r=>r.id===id),s=document.getElementById('role-skill-'+id).value;if(!r.skills.includes(s)){r.skills.push(s);r.evidence[s]='Manually added by you for this role.'}ds.draftReviewed=false;render()}
dConfirmProfile=function(){if(!ds.draftReviewed){document.getElementById('review-error').textContent='Review each role-skill connection and check the confirmation box first.';return}if(ds.roleDraft.some(r=>!r.title.trim())){document.getElementById('review-error').textContent='Give each role a title, or remove it.';return}ds.roles=structuredClone(ds.roleDraft);ds.skills=[...new Set(ds.roles.flatMap(r=>r.skills))];ds.reviewed=true;go('/discover');notify('Role experience is ready. Click a skill to find related contributions.')};
dSkipProfile=function(){ds.roles=[];ds.roleDraft=[];ds.skills=[];ds.reviewed=false;ds.draftReviewed=false;go('/discover');notify('Explore freely. No prior experience is required to browse.')};
// Compact, action-first fit view. Full evidence is available on demand.
function fitDonut(r,compact=false){const value=Math.max(0,Math.min(100,r.low)),angle=value*3.6;return `<div class="fit-donut ${compact?'fit-donut-small':''}" style="--fit-angle:${angle}deg" role="img" aria-label="${value} out of 100 ${r.knownWeight<100?'supported fit points so far; some information is unknown':'fit points'}"><div class="fit-donut-center"><strong>${value}</strong><span>/ 100</span></div></div>`}
function briefFitReasons(r){let reasons=[];if(ds.mode==='interests'&&ds.cause!=='any'&&r.opportunity.cause===ds.cause)reasons.push('Supports '+ds.cause.toLowerCase()+'.');if(ds.mode==='experience'&&r.matched.length){const m=r.matched.find(m=>ds.useSkills.includes(m.skill))||r.matched[0];reasons.push('Builds on '+m.skill+' from '+m.role+'.')}else if(r.useMatches.length)reasons.push('A chance to use '+r.useMatches.slice(0,2).join(' and ')+'.');if(r.learnMatches.length)reasons.push('Practice '+r.learnMatches.slice(0,2).join(' and ')+' with support.');if(!reasons.length)reasons.push(r.opportunity.outcome);return reasons.slice(0,2)}
function fitBreakdown(r){return `<details class="fit-more"><summary>See why this fits</summary><div class="fit-more-content"><p class="discover-note">${DM.modes[ds.mode]}. Fit points help compare opportunities; they are not a qualification or a probability.</p>${r.knownWeight<100?`<p class="discover-note">Supported score: ${r.low}. Possible range: ${r.low}–${r.high} while details remain unknown.</p>`:''}<table class="fit-table"><thead><tr><th scope="col">Factor</th><th scope="col">Weight</th><th scope="col">Points</th></tr></thead><tbody>${r.components.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.explanation)}</small></td><td>${c.weight}%</td><td>${c.weight===0?'0':c.points===null?'0–'+c.weight:Number(c.points.toFixed(1))}</td></tr>`).join('')}</tbody></table>${r.matched.length?`<h3 style="margin-top:20px">Your role connection</h3>${r.matched.map(m=>`<div class="evidence-row"><strong>${esc(m.skill)} · ${esc(m.role)}</strong><p>“${esc(m.evidence)}”</p><span class="source-label">Your reviewed statement · not independently verified</span></div>`).join('')}`:'<p class="discover-note">Add reviewed role experience to give this recommendation more context.</p>'}<a class="textlink" href="#/discover/profile">Review my background →</a></div></details>`}
const priorDetailBeforeCompact=dDetail;
const sampleOrgDescriptions={
 'tax':'A sample community program helping neighbors access supervised tax-preparation support.',
 'budget':'A sample community collective bringing people together through neighborhood events.',
 'forest':'A sample neighborhood crew supporting tree planting and local green spaces.',
 'pantry':'A sample community pantry helping neighbors access food and essential supplies.',
 'pantry-budget':'A sample community pantry helping neighbors access food and essential supplies.',
 'mentor':'A sample learning program supporting students through supervised homework activities.',
 'design':'A sample arts group using creative projects to bring neighbors together.',
 'creek':'A sample conservation group caring for local waterways and shared outdoor spaces.',
 'animal-outreach':'A sample animal-welfare group helping shelter animals connect with caring homes.'
};
function opportunityTag(text,kind=''){return `<span class="op-detail-tag ${kind}">${esc(text)}</span>`}
dDetail=function(id){
 const o=DO.find(x=>x.id===id);if(!o)return priorDetailBeforeCompact(id);
 const r=DM.evaluate(o,ds),orgName=o.org.replace(/\s*·\s*fictional(?: provider)?/i,'');
 const saved=ds.saved.has(o.id),description=sampleOrgDescriptions[o.id]||'A sample community organization offering supervised volunteering opportunities.';
 return `<div class="scan-opportunity"><a class="textlink" href="#/discover">← All opportunities</a>
 <section class="org-banner" aria-label="About the organization"><div class="org-banner-identity"><span class="org-emblem" aria-hidden="true">${icon('leaf')}</span><div><span class="org-banner-label">THE ORGANIZATION</span><h2>${esc(orgName)}</h2><span class="org-banner-demo">Fictional organization · preview</span></div></div><div class="org-banner-about"><span class="org-banner-label">WHAT THEY DO</span><p>${esc(description)}</p></div></section>
 <section class="scan-role-heading"><div class="scan-role-kicker"><span class="eyebrow">VOLUNTEER OPPORTUNITY</span><span class="source-label">DEMO LISTING</span></div><h1>${esc(o.role)}</h1><p>${esc(o.outcome)}</p><div class="op-tag-row" aria-label="Opportunity at a glance">${opportunityTag(o.cause,'cause')}${opportunityTag(formatName(o))}${opportunityTag(o.weeks===1?'One event':o.weeks+' weeks')}${opportunityTag(o.day)}${opportunityTag(o.level)}</div><button class="btn scan-mobile-save" aria-pressed="${saved}" onclick="dBookmark('${o.id}')">${saved?'✓ Saved for later':'Save for later +'}</button></section>
 <div class="scan-detail-grid"><section class="scan-description"><div class="card scan-description-card"><h2>About the opportunity</h2><p class="scan-summary">${esc(o.deliverable)}</p><ul class="scan-task-list">${o.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="scan-skills"><div><h3>Skills you’ll use</h3><div class="op-tag-row">${o.required.length?o.required.map(t=>opportunityTag(t)).join(''):opportunityTag('No prior skills required')}</div></div><div><h3>Skills you could practice</h3><div class="op-tag-row">${o.practice.map(t=>opportunityTag(t,'practice')).join('')}</div></div></div><div class="scan-logistics"><div><span>WHEN</span><strong>${o.day}</strong><p>${esc(o.time)}</p></div><div><span>COMMITMENT</span><strong>${o.weeks===1?'One event':o.weeks+' weeks'}</strong><p>${formatName(o)}</p></div>${o.format==='remote'?'<div><span>WHERE</span><strong>Remote</strong><p>No commute</p></div>':`<div><span>JOURNEY</span><strong>${r.travel===null?'To confirm':r.travel+' min one way'}</strong><p>${r.travel===null?'Ask the organizer':'Sample '+esc(ds.transport)+' estimate'}</p></div>`}</div><div class="scan-support"><h3>Support you’ll have</h3><p>${esc(o.supportNote)}</p>${o.training?`<div class="scan-requirement"><strong>Before you start</strong><p>${esc(o.training)}</p></div>`:''}${r.gaps.length?`<p class="scan-requirement-note">Confirm with the organizer: ${esc(r.gaps.join(', '))}. A missing profile tag doesn’t establish your ability.</p>`:''}</div></div><details class="scan-source"><summary>Source & listing details</summary><p>This provider and opportunity are fictional examples. Requirements, schedules and routes are sample data. No application is available from this preview.</p>${o.id==='tax'?'<a class="textlink" href="https://www.irs.gov/individuals/irs-tax-volunteers" target="_blank" rel="noopener noreferrer">Explore real VITA volunteering at IRS.gov ↗</a>':''}</details></section>
 <section class="card scan-fit-card" aria-label="Your fit and save"><h2>Your fit, explained.</h2><div class="fit-visual-row">${fitDonut(r)}<div><h3>${r.knownWeight<100?'Your fit so far':'Your fit'}</h3><p class="fit-caption">${r.knownWeight<100?'Some details need confirming.':'Based on your preferences.'}</p></div></div><ul class="fit-short-reasons">${briefFitReasons(r).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${r.reasons.length?`<p class="fit-attention">${esc(r.reasons[0])}</p>`:''}${r.status==='conditional'?'<p class="fit-attention">Confirm missing travel details before deciding.</p>':''}<button class="btn wide fit-save" aria-pressed="${saved}" onclick="dBookmark('${o.id}')">${saved?'✓ Saved for later':'Save for later +'}</button><p class="fit-save-note">${saved?'Saved on this device. Click again to remove.':'Keep this opportunity. No application submitted.'}</p>${fitBreakdown(r)}<a class="scan-change-link" href="#/discover">Explore other opportunities →</a></section></div></div>`;
};
// Browsing cards retain their original description and simple fit display.
render();
